#!/usr/bin/env ruby
require 'json';require 'open3';require 'fileutils';root=File.expand_path('..',__dir__);poms=Dir.glob(File.join(root,'**/pom.xml'));joined=poms.map{|p|File.read(p)}.join("\n");jdk=File.expand_path('../.toolchains/jdk-26.0.2.1.jdk/Contents/Home',root);env={'JAVA_HOME'=>jdk,'PATH'=>"#{jdk}/bin:#{ENV['PATH']}"};o,e,st=Open3.capture3(env,'./mvnw','-pl','server/gameServer,server/LegacyGameHall','-am','-DskipTests','package','-q',chdir:root);c={'no_legacy_kernel'=>!joined.include?('com.aoo.legacy'),'no_legacy_repository'=>!joined.include?('<id>aoo-legacy</id>'),'modern_build_passed'=>st.success?};r={'task'=>'JAVA11','passed'=>c.values.all?,'checks'=>c,'buildStdout'=>o.strip,'buildStderr'=>e.strip};p=File.join(root,'work/audit/legacy-runtime-isolation.json');FileUtils.mkdir_p(File.dirname(p));File.write(p,JSON.pretty_generate(r)+"\n");puts JSON.generate(r);exit(r['passed'] ? 0 : 1)
